        code: true,
        python: "cesta = {'manzana', 'naranja', 'manzana', 'pera', 'naranja', 'plátano'}\n# Un conjunto no tiene orden: sorted() solo es para mostrarlo ordenado\nprint(sorted(cesta))          # sin repetidos\nprint('naranja' in cesta)\nprint('kiwi' in cesta)\n\na = set('abracadabra')\nb = set('alacazam')\nprint(sorted(a))          # letras únicas de a\nprint(sorted(a - b))      # en a pero no en b\nprint(sorted(a | b))      # en a, en b o en ambos\nprint(sorted(a & b))      # en a y en b\nprint(sorted(a ^ b))      # en a o en b, pero no en ambos\n\nprint(sorted({x for x in 'abracadabra' if x not in 'abc'}))",
        php: "// PHP no tiene conjuntos: se usan arreglos sin repetidos\n$cesta = array_unique(['manzana', 'naranja', 'manzana', 'pera', 'naranja', 'plátano']);\nsort($cesta);\necho json_encode($cesta, JSON_UNESCAPED_UNICODE), \"\\n\";\nvar_dump(in_array('naranja', $cesta));\nvar_dump(in_array('kiwi', $cesta));\n\n$a = array_unique(str_split('abracadabra'));\n$b = array_unique(str_split('alacazam'));\n$ver = function ($conjunto) { sort($conjunto); return json_encode($conjunto); };\necho $ver($a), \"\\n\";                                                    // letras únicas de a\necho $ver(array_diff($a, $b)), \"\\n\";                                    // en a pero no en b\necho $ver(array_unique(array_merge($a, $b))), \"\\n\";                     // en a, en b o en ambos\necho $ver(array_intersect($a, $b)), \"\\n\";                               // en a y en b\necho $ver(array_merge(array_diff($a, $b), array_diff($b, $a))), \"\\n\";   // en uno, no en ambos",
        java: "// TreeSet guarda los elementos sin repetir y ordenados\nSet<String> cesta = new TreeSet<>(List.of(\"manzana\", \"naranja\", \"manzana\", \"pera\", \"naranja\", \"plátano\"));\nSystem.out.println(cesta);\nSystem.out.println(cesta.contains(\"naranja\"));\nSystem.out.println(cesta.contains(\"kiwi\"));\n\nSet<Character> a = new TreeSet<>();\nfor (char c : \"abracadabra\".toCharArray()) a.add(c);\nSet<Character> b = new TreeSet<>();\nfor (char c : \"alacazam\".toCharArray()) b.add(c);\nSystem.out.println(a);                 // letras únicas de a\n\nSet<Character> diferencia = new TreeSet<>(a);\ndiferencia.removeAll(b);\nSystem.out.println(diferencia);        // en a pero no en b\n\nSet<Character> union = new TreeSet<>(a);\nunion.addAll(b);\nSystem.out.println(union);             // en a, en b o en ambos\n\nSet<Character> interseccion = new TreeSet<>(a);\ninterseccion.retainAll(b);\nSystem.out.println(interseccion);      // en a y en b",
