        php: "$tel = ['juan' => 4098, 'ana' => 4139];\n$tel['guido'] = 4127;\necho json_encode($tel), \"\\n\";\necho $tel['juan'], \"\\n\";\nvar_dump($tel['irene'] ?? null);   // null si la clave no existe\nunset($tel['ana']);\n$tel['irene'] = 4127;\necho json_encode($tel), \"\\n\";\necho json_encode(array_keys($tel)), \"\\n\";   // las claves, en orden de llegada\n$claves = array_keys($tel);\nsort($claves);\necho json_encode($claves), \"\\n\";            // las claves, ordenadas\nvar_dump(array_key_exists('guido', $tel));\nvar_dump(!array_key_exists('juan', $tel));",
