        code: true,
        python: "a, b, c = 1, 5, 10\nprint(a < b < c)        # comparaciones encadenadas\nprint(a < b == c)\nprint(3 in [1, 2, 3])   # pertenencia\nprint(not (a > b))\n\ncadena1, cadena2, cadena3 = '', 'Trondheim', 'Hammer Dance'\nno_vacia = cadena1 or cadena2 or cadena3   # el primer valor que no esté vacío\nprint(no_vacia)\n\nif (n := len(cadena2)) > 5:   # asignar dentro de una condición con :=\n    print(f'«{cadena2}» tiene {n} letras')",
        php: "[$a, $b, $c] = [1, 5, 10];\nvar_dump($a < $b && $b < $c);   // PHP no encadena comparaciones\nvar_dump($a < $b && $b == $c);\nvar_dump(in_array(3, [1, 2, 3]));\nvar_dump(!($a > $b));\n\n[$cadena1, $cadena2, $cadena3] = ['', 'Trondheim', 'Hammer Dance'];\n$noVacia = $cadena1 ?: $cadena2 ?: $cadena3;   // el primer valor que no esté vacío\necho $noVacia, \"\\n\";\n\nif (($n = strlen($cadena2)) > 5) {   // en PHP se puede asignar dentro de la condición\n    echo \"«{$cadena2}» tiene $n letras\\n\";\n}",
