        php: "$f = fopen('archivo.txt', 'w');\necho fwrite($f, \"Esta es la primera línea del archivo.\\n\"), \"\\n\";   // devuelve los BYTES escritos (la í ocupa 2)\nfwrite($f, \"Segunda línea del archivo\\n\");\nfclose($f);\n\n$f = fopen('archivo.txt', 'r');\nvar_dump(fgets($f));\nvar_dump(fgets($f));\nvar_dump(fgets($f));   // false al llegar al final\nfclose($f);\n\nforeach (file('archivo.txt') as $linea) {   // recorrer línea por línea\n    echo $linea;\n}\n\n$f = fopen('archivo.bin', 'w+b');   // modo binario\nfwrite($f, '0123456789abcdef');\nfseek($f, 5);                       // ir al byte 5\necho fread($f, 1), \"\\n\";\nfseek($f, -3, SEEK_END);            // 3 bytes antes del final\necho fread($f, 1), \"\\n\";\necho ftell($f), \"\\n\";               // posición actual\nfclose($f);",
