export const LEARN_ROUTE = '#/aprende'

export function isLearnRoute(hash) {
  return hash === LEARN_ROUTE || hash.startsWith(`${LEARN_ROUTE}/`)
}

export function getLearnModule(hash) {
  const id = hash.slice(LEARN_ROUTE.length + 1)
  return learnModules.find((module) => module.id === id) ?? learnModules[0]
}
